if(!exists('asset_pool_backtest'))library(creditratingsystem)
spa_D<-'2023-01-01';spa_dates<-list('2023-07-01','2024-01-01')
spa_asset<-function(id='a',group='g')list(asset_id=id,asset_class='AUTO_LOAN',invoice_id=NULL,obligor_id=group,default_group_id=group,seller_id='seller',servicer_id='service',currency='EUR',observed_at=spa_D,known_at=spa_D,origination_date='2022-01-01',balance_date=spa_D,principal_balance=100,schedule=list(list(date=spa_dates[[1]],principal_due=40,interest_due=5),list(date=spa_dates[[2]],principal_due=60,interest_due=3)),overdue_days=0,disputed=FALSE,dilution_reserve=0,recourse='NONE',collateral_allocations=list())
spa_assignment<-function(id='m',aid='a',start=spa_D,price=100)list(assignment_id=id,pool_id='pool',asset_id=aid,known_at=spa_D,effective_from=start,effective_until=NULL,share=1,purchase_price=price,purchase_priority=1)
spa_fixture<-function(assets=list(spa_asset()),assignments=list(spa_assignment()),revolving=FALSE){
 p<-list(profile_id='p',version='1',known_at=spa_D,currency='EUR',product_kind='ABS',pool_mode=if(revolving)'REVOLVING'else'STATIC',allowed_asset_classes=list('AUTO_LOAN'),maximum_dpd=30,exclude_disputed=TRUE,eligible_recourse=list('NONE'),revolving_until=if(revolving)spa_dates[[2]]else NULL)
 pool<-build_credit_asset_pool(assets,assignments,p,'pool',spa_D,spa_D)$value
 contract<-list(contract_id='c',version='1',scenario_ids=list('s'),weights=list(1),dates=spa_dates,currency='EUR',probability_measure='PHYSICAL',sampling_design='FIXED_WEIGHTED_SCENARIOS',conditioning='PIT',default_timing='BEFORE_DUE',prepayment_timing='AFTER_COUPON',dilution_treatment='PROPORTIONAL_REMAINING_SCHEDULE',reinvestment_funding='PRINCIPAL_CASH_ONLY',initial_reinvestment_cash=0)
 gp<-ap<-innov<-list();for(g in sort(unique(vapply(assets,function(a)a$default_group_id,''))))for(d in spa_dates){gp[[length(gp)+1L]]<-list(scenario_id='s',default_group_id=g,date=d,conditional_pd=0,default_channel=paste0('default-',g));innov[[length(innov)+1L]]<-list(scenario_id='s',date=d,channel_id=paste0('default-',g),uniform=.5)}
 for(a in assets)for(d in spa_dates){ap[[length(ap)+1L]]<-list(scenario_id='s',asset_id=a$asset_id,date=d,conditional_prepayment_probability=0,prepayment_channel=paste0('prepay-',a$asset_id),dilution_fraction=0,recovery_fraction=.4,recovery_delay_days=30,recovery_cost=5,servicing_cost=0,interest_multiplier=1,overdue_days=0,disputed=FALSE);innov[[length(innov)+1L]]<-list(scenario_id='s',date=d,channel_id=paste0('prepay-',a$asset_id),uniform=.5)}
 list(asset_pool=pool,scenario_contract=contract,obligor_paths=gp,asset_paths=ap,shared_innovations=innov)
}
spa_run<-function(f)do.call(simulate_asset_pool,f)$value
spa_total<-function(r,key)sum(vapply(r$cashflows,function(c)c[[key]],0.))
spa_error<-function(code,expr){e<-tryCatch(force(expr),error=identity);stopifnot(inherits(e,'creditratingsystem_error'),e$code==code)}

vap_fixture<-function(prepay=FALSE){
 base<-spa_fixture();pool<-base$asset_pool;pi<-list(asset_contracts=list(spa_asset()),pool_assignments=list(spa_assignment()),eligibility_profile=pool$profile,pool_id='pool',as_of=spa_D,information_cutoff=spa_D)
 base$scenario_contract$scenario_ids<-list('d','n');base$scenario_contract$weights<-list(.5,.5)
 for(field in c('obligor_paths','asset_paths','shared_innovations')){original<-base[[field]];base[[field]]<-unlist(lapply(c('d','n'),function(s)lapply(original,function(row){row$scenario_id<-s;row})),recursive=FALSE)}
 base$obligor_paths<-lapply(base$obligor_paths,function(row){row$conditional_pd<-if(row$date=='2023-07-01').5 else 0;row});base$shared_innovations<-lapply(base$shared_innovations,function(row){row$uniform<-if(row$scenario_id=='d').25 else .75;row})
 target<-list(event='default',horizon=365,time_unit='days',probability_measure='PHYSICAL',conditioning='PIT');design<-list(model_id='pool-model',model_version='1',parameter_version='1',data_fingerprint='actual-servicer-file',population_id='pool',split_id='holdout',prediction_origin='HOLDOUT',evaluation_cutoff='2024-01-02',forecast_known_at=spa_D,currency='EUR',target=target)
 fields<-c('scheduled_principal','prepayment_principal','default_ead','dilution','interest','recovery_gross','workout_cost','servicing_cost')
 event<-function(id,date,kind,opening,closing,...){flows<-list(...);e<-list(event_id=id,asset_id='a',date=date,known_at=date,sequence=1,currency='EUR',event_type=kind,opening_principal=opening,closing_principal=closing);for(k in fields)e[[k]]<-if(is.null(flows[[k]]))0 else flows[[k]];e['default_event_id']<-list(flows$default_event_id);e}
 events<-if(prepay)list(event('prepay','2023-07-01','PREPAYMENT',100,0,prepayment_principal=100,interest=5))else list(event('default','2023-07-01','DEFAULT',100,0,default_ead=100),event('recovery','2023-07-31','RECOVERY',0,0,recovery_gross=30,workout_cost=5,default_event_id='default'))
 allocations<-lapply(events,function(e)list(allocation_id=paste0('alloc-',e$event_id),event_id=e$event_id,pool_id='pool',share=1,known_at=e$known_at,amounts=e[fields]));accounts<-payments<-list()
 for(e in events){principal<-if(prepay)80 else if(e$event_type=='RECOVERY')25 else 0;interest<-if(prepay)5 else 0;accounts[[length(accounts)+1L]]<-list(date=e$date,known_at=e$date,currency='EUR',opening_cash=0,closing_cash=0,purchase_cash=0,sale_cash=0,external_injection=0,external_distribution=0,fees_paid=0,tranche_interest_paid=interest,tranche_principal_paid=principal,equity_paid=if(prepay)20 else 0);if(principal>0)payments[[length(payments)+1L]]<-list(payment_id=paste0('pay-',e$event_id),tranche_id='senior',date=e$date,known_at=e$date,currency='EUR',principal=principal,interest=interest)}
 list(asset_pool=pool,pool_inputs=pi,forecast_paths=spa_run(base),forecast_inputs=base,servicing=events,allocations=allocations,pool_accounts=accounts,coverage=list(list(asset_id='a',complete=TRUE,complete_through='2024-01-01',known_at='2024-01-02',currency='EUR',target=target)),design=design,cash_contract=list(as_of=spa_D,known_at=spa_D,currency='EUR',opening_cash=0),tranche_contracts=list(list(tranche_id='senior',notional=80,currency='EUR',known_at=spa_D)),tranche_payments=payments)
}
vap_run<-function(kw)do.call(asset_pool_backtest,kw)$value
r<-vap_run(vap_fixture());stopifnot(r$decision$status=='NOT_ASSESSED',!length(r$violations),r$metrics$default_probability$brier==.25,r$metrics$pool_cash_errors$recovery_gross$bias == -10,r$metrics$tranche_payments$senior$principal==25,all(vapply(r$cash_residuals,function(x)x$residual==0,TRUE)))
r<-vap_run(vap_fixture(TRUE));stopifnot(r$metrics$default_probability$observed_rate==0,r$metrics$prepayment_probability$observed_rate==1,r$metrics$tranche_payments$senior$principal==80)
f<-vap_fixture();a<-f$allocations[[2]];a$allocation_id<-'duplicate-claim';a$pool_id<-'other';f$allocations[[3]]<-a;stopifnot(vap_run(f)$violation_counts$CASH_OR_LOSS_DOUBLE_ALLOCATION==1)
f<-vap_fixture();f$servicing[[2]]$known_at<-'2024-02-01';f$coverage[[1]]$complete<-FALSE;f$pool_accounts<-f$pool_accounts[1];f$tranche_payments<-list();r<-vap_run(f);stopifnot(r$coverage$eligible_assets==0,is.null(r$metrics$pool_cash_errors$recovery_gross$bias),r$metrics$observed_owned_flows$recovery_gross==0)
f<-vap_fixture();f$coverage[[1]]$known_at<-spa_D;spa_error('VALIDATION_ASSET_POOL',vap_run(f))
f<-vap_fixture();f$servicing[[1]]$closing_principal<-1;stopifnot(vap_run(f)$violation_counts$ASSET_PRINCIPAL_CONSERVATION==1)
f<-vap_fixture();f$pool_accounts[[2]]$tranche_principal_paid<-24;r<-vap_run(f);stopifnot(r$violation_counts$POOL_CASH_CONSERVATION==1,r$violation_counts$TRANCHE_CASH_RECONCILIATION==1)
cat('Native actual asset servicing, prepayment, incomplete coverage and cash/tranche reconciliation PASS\n')
f<-vap_fixture();h<-f$pool_inputs$pool_assignments[[1]];h$share<-.5;f$ownership_history<-list(h);f$allocations<-lapply(f$allocations,function(a){a$share<-.5;a$amounts<-lapply(a$amounts,function(v)v*.5);a});f$pool_accounts[[2]]$tranche_principal_paid<-12.5;f$tranche_payments[[1]]$principal<-12.5;r<-vap_run(f);stopifnot(!length(r$violations),r$metrics$observed_owned_flows$recovery_gross==15,r$coverage$forecast_comparison_risk_set=='NOT_COMPARABLE',is.null(r$metrics$default_probability$brier),is.null(r$metrics$pool_cash_errors$recovery_gross$bias))

f<-vap_fixture(TRUE);e<-f$servicing[[1]];e$event_id<-'after-exit';e$date<-e$known_at<-'2023-07-31';e$event_type<-'PAYMENT';e$opening_principal<-e$prepayment_principal<-0;e$interest<-1;f$servicing[[2]]<-e;stopifnot(vap_run(f)$violation_counts$POST_PREPAYMENT_PERFORMING_CASH==1)
